/bin/bash -lc "python3 - <<'PY'
import subprocess,json
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))
for k,v in r.items():
 if k"'!='"'context': print(k, json.dumps(v,indent=2))
print('CONTEXT KEYS',list(r.get('context',{})))
for k,v in r.get('context',{}).items():
 if k"'!='"'history': print('CONTEXT', k, json.dumps(v,indent=2))
print('HISTORY SUMMARY')
for h in r.get('context',{}).get('history',[]):
 print(json.dumps({k:v for k,v in h.items() if k not in ['validation','config','candidate_diagnostics']},default=str))
 print('auc', h.get('validation',{}).get('auc'),'inference',h.get('validation',{}).get('inference_seconds'))
PY"

