/bin/bash -lc "python3 - <<'PY'
import ast,hashlib,json,pathlib
p=pathlib.Path('.')
r=json.loads((p/'runtime.json').read_text()); w=json.loads((p/'workspace.json').read_text()); q=json.loads((p/'proposal.json').read_text())

def validate(value,schema,path='"'$'"'):
 typ=schema.get('type')
 good={'object':lambda x:isinstance(x,dict),'array':lambda x:isinstance(x,list),'string':lambda x:isinstance(x,str),'boolean':lambda x:isinstance(x,bool),'integer':lambda x:isinstance(x,int) and not isinstance(x,bool),'number':lambda x:isinstance(x,(int,float)) and not isinstance(x,bool)}
 if typ: assert good[typ](value),(path,typ,type(value))
 if 'const' in schema: assert value==schema['const'],path
 if 'enum' in schema: assert value in schema['enum'],path
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=set(value),(path,'required')
  properties=schema.get('properties',{})
  if schema.get('additionalProperties') is False: assert set(value)<=set(properties),(path,'extra',set(value)-set(properties))
  for k,v in value.items():
   if k in properties:validate(v,properties[k],path+'.'+k)
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  for i,item in enumerate(value):
   if 'items' in schema:validate(item,schema['items'],path+'['+str(i)+']')
 if isinstance(value,str):assert len(value)>=schema.get('minLength',0),path
validate(q['study'],r['study_schema'])
assert set(q)=={'study','parent_trial','variants','knowledge_assessments'}
assert q['study']['protocol_ref']==r['required_study_protocol_ref']==w['protocol_hash']
allowed=set(r['context']['allowed_observation_ids'])
assert q['parent_trial'] in allowed
assert set(q['study']['evidence_refs'])<=allowed
assert all(x['parent_ref'] in allowed for x in q['study']['contrasts'])
assert 1<=len(q['variants'])<=4
assert len(set(x['name'] for x in q['variants']))==len(q['variants'])
assert len(set(x['file'] for x in q['variants']))==len(q['variants'])
assert sum(x['role']=='candidate' for x in q['variants'])==1
parent=ast.parse((p/'history_g2_r0065_basis96_native.py').read_text())
parent_classes={n.name:n for n in parent.body if isinstance(n,ast.ClassDef)}
new_trees=[]
for v in q['variants']:
 assert set(v)=={'name','file','role','config','note'}
 f=v['file'];assert pathlib.Path(f).name==f and f.endswith('.py')
 src=(p/f).read_text();tree=ast.parse(src);compile(src,f,'exec')
 config=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 assert config==v['config'],f
 model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model');init=next(n for n in model.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 argnames={a.arg for a in init.args.args+init.args.kwonlyargs};assert set(config)<=argnames,(f,set(config)-argnames)
 for n in ast.walk(tree):
  if isinstance(n,ast.Import):assert all(x.name.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'} for x in n.names)
  if isinstance(n,ast.ImportFrom):assert n.level==0 and n.module.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','eval','exec','compile','__import__','input'}
 for cls in [n for n in tree.body if isinstance(n,ast.ClassDef)]:
  old=parent_classes[cls.name]
  for fn in [n for n in cls.body if isinstance(n,ast.FunctionDef)]:
   oldfn=next(n for n in old.body if isinstance(n,ast.FunctionDef) and n.name==fn.name)
   if fn.name=='__init__' and cls.name in {'Model','_ContextAffine'}:continue
   assert ast.dump(fn)==ast.dump(oldfn),(f,cls.name,fn.name)
 if v['name'].startswith('dense'):new_trees.append(tree)
 sha=hashlib.sha256(src.encode()).hexdigest();assert sha in v['note']
 print(f,'syntax/config/API/imports/AST/hash: PASS',sha)
# Both new modules differ in executable AST only by literal CONFIG rank.
for t in new_trees:
 t.body=[n for n in t.body if not (isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))]
assert ast.dump(new_trees[0])==ast.dump(new_trees[1])
assert (p/'control_factor96.py').read_bytes()==(p/'history_g2_r0065_basis96_native.py').read_bytes()
assert (p/'control_factor88.py').read_bytes()==(p/'history_g2_r0065_basis88_native.py').read_bytes()
for a in w['available_ancestor_sources']:
 assert hashlib.sha256((p/a['file']).read_bytes()).hexdigest()==a['source_sha256'],a['file']
assert hashlib.sha256((p/'baseline_reference.py').read_bytes()).hexdigest()==r['context']['protocol']['source_sha256']['baseline.py']
ids={a['knowledge_id'] for a in q['knowledge_assessments']}
assert {a['knowledge_id'] for a in r['context']['latest_knowledge_usage']['assessments']}<=ids
assert all(a['decision'] in ['used','considered','rejected','unresolved'] and all(a[k] for k in ['rationale','transformed_mechanism','nearest_work_difference','falsifier']) for a in q['knowledge_assessments'])
# Analytic count differences from accepted same-architecture factor receipts.
context_width=192;output_width=112
for rank in (96,88):
 fact=rank*(context_width+output_width);dense=context_width*output_width
 ref=next(h for h in r['context']['history'] if h['id']=='g2-r0065-basis'+str(rank)+'_native')
 assert ref['dense_parameters']-fact+dense==192883
 assert ref['parameters']-fact+dense==31986099
 print('rank',rank,'context factor/dense/saving',fact,dense,fact-dense)
print('Study schema, protocol/evidence/lineage, standalone4-cell suite, native byte identity, all nonconstructor ASTs,15 assessments, protected digests and analytic counts: PASS')
print('No PyTorch/tensor execution, authoritative validator, model training, new AUC or measured speedup claimed.')
PY"

